resources.preRequestScript:
const run = Date.now().toString();
for (const kind of ['client', 'workshop', 'rejected', 'other']) insomnia.environment.set(kind + '_email', kind + '.' + run + '@kelsets.example');
for (const key of ['vehicle_id', 'dealership_id', 'workshop_id', 'rejected_workshop_id', 'appointment_id', 'other_appointment_id']) insomnia.environment.set(key, '');
const next = new Date(Date.now() + 7 * 86400000);
function slot(value) {
 while ([0,6].includes(value.getUTCDay())) value.setUTCDate(value.getUTCDate() + 1);
 const day = value.toISOString().slice(0,10);
 const probe = new Date(day + 'T10:00:00Z');
 const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(probe).map(p => [p.type,p.value]));
 const offset = Date.UTC(+parts.year,+parts.month-1,+parts.day,+parts.hour,+parts.minute,+parts.second) - probe.getTime();
 return new Date(probe.getTime()-offset).toISOString();
}
insomnia.environment.set('appointment_date', slot(next));
next.setUTCDate(next.getUTCDate()+1);
insomnia.environment.set('other_date', slot(next));

